// [Blur2PC][macOS] Original PC L8 DDS files, exact GPU storage/view sampling and graph failure rollback.
#include <display.h>
#include <render/postprocess/Manager.h>
#include <render/postprocess/Interface.h>
#include <system/serialise.h>
#include <system/serialise/macos/NativeFile.h>
#include <filesystem>
#include <fstream>
#include <vector>
#include <cstring>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
static void require(bool value,const char* why){if(!value){std::cerr<<why<<std::endl;throw std::runtime_error(why);}}
static U32 word(const std::vector<U8>& b,U32 o){U32 v=0;for(U32 i=0;i<4;++i)v|=U32(b[o+i])<<(i*8);return v;}
static void word(std::vector<U8>& b,U32 o,U32 v){for(U32 i=0;i<4;++i)b[o+i]=U8(v>>(i*8));}
static std::vector<U8> read(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);require(bool(f),"L8 fixture file absent");return {std::istreambuf_iterator<char>(f),std::istreambuf_iterator<char>()};}
static void write(const std::filesystem::path& p,const std::vector<U8>& b){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(b.data()),b.size());require(bool(f),"L8 fixture write failed");}
static std::vector<U8> dds(bool fourcc){std::vector<U8>b(128);std::memcpy(b.data(),"DDS ",4);word(b,4,124);word(b,8,0x2100f);word(b,12,3);word(b,16,5);word(b,20,5);word(b,28,3);word(b,76,32);word(b,80,fourcc?4:0x20000);word(b,84,fourcc?50:0);word(b,88,8);word(b,92,255);word(b,108,0x401008);for(U32 l=0;l<3;++l)for(U32 y=0;y<std::max(1U,3U>>l);++y)for(U32 x=0;x<std::max(1U,5U>>l);++x)b.push_back(U8(17+l*61+x*13+y*29));return b;}
static std::vector<U8> shader(bool vertex){const std::string bindings=vertex?"\"ubos\":[]":"\"ubos\":[{\"binding\":0,\"block_size\":16,\"name\":\"Dimensions\"}],\"textures\":[{\"binding\":0,\"type\":\"texture2D\"}]";const std::string metadata=std::string("{\"parameters\":{},\"input_semantics\":")+(vertex?"[[0,0,0]]":"[]")+",\"reflection\":{"+bindings+"}}";const std::string source=std::string("#include <metal_stdlib>\nusing namespace metal;\n")+(vertex?"struct I{float2 p[[attribute(0)]];};vertex float4 blur_main(I i[[stage_in]]){return float4(i.p,.5,1);}":"fragment float4 blur_main(float4 p[[position]],constant float4& d[[buffer(0)]],texture2d<float> t[[texture(0)]],sampler s[[sampler(0)]]){return t.sample(s,p.xy/d.xy,level(d.z));}");const std::string entry="blur_main";std::vector<U8>b(40);std::memcpy(b.data(),"BMSL",4);word(b,4,1);word(b,8,vertex?0:1);word(b,16,40);word(b,20,metadata.size());word(b,24,40+metadata.size());word(b,28,source.size());word(b,32,40+metadata.size()+source.size());word(b,36,entry.size());b.insert(b.end(),metadata.begin(),metadata.end());b.insert(b.end(),source.begin(),source.end());b.insert(b.end(),entry.begin(),entry.end());word(b,12,b.size());return b;}
struct FailureState{U32 created=0,destroyed=0;};
class FileEffect final:public PostProcess::I_PostProcess {
    FailureState& state;Display::C_Texture2D texture,invalid;
public:
    FileEffect(PostProcess::C_Manager& m,FailureState& s):I_PostProcess(m),state(s){}
    bool Create()override{++state.created;return Display::CreateTexture2DFromFile("valid.dds",&texture)&&Display::CreateTexture2DFromFile("bad.dds",&invalid);}
    void Destroy()override{++state.destroyed;Display::Device()->Destroy(&texture);Display::Device()->Destroy(&invalid);}
    bool CreateVolatile()override{return false;}void DestroyVolatile()override{}void Update()override{}
};
int main(int argc,char**argv){try{
    require(argc==2,"Expected writable L8 DDS fixture directory");const auto root=std::filesystem::absolute(argv[1]);std::filesystem::create_directories(root);auto& fs=Sys::C_FileSystem::Instance();Sys::SetDefaultFileSystem(&fs);require(fs.SetWorkingDirectory(root.string().c_str()),"L8 fixture filesystem failed");Display::C_Device device;Display::C_DeviceParams params;params.m_Width=19;params.m_Height=11;require(device.Create(params)&&device.CreateVolatile(params),"L8 fixture native device failed");auto& native=device.GetDisplay2();auto& c=native.GetContext();Display2::C_VertexShader vs;Display2::C_PixelShader ps;auto v=shader(true),p=shader(false);std::string error;require(native.CreateVertexShader(v.size(),v.data(),0,&vs,nullptr,&error),error.c_str());require(native.CreatePixelShader(p.size(),p.data(),0,&ps,nullptr,&error),error.c_str());Display2::C_VertexDeclaration declaration;Display2::C_VertexFormat format;format.AddElement(0,0,Display2::E_VertexElementType_F32_2,Display2::E_VertexElementUsage_Position,0);Display2::C_VertexBuffer vertices;require(native.CreateVertexDeclaration(format,&declaration)&&native.CreateVertexBuffer(32,0,&vertices),"L8 fixture geometry failed");const F32 quad[]={-1,1,1,1,-1,-1,1,-1};auto out=vertices.Lock();require(out,"L8 geometry map failed");std::memcpy(out,quad,sizeof(quad));vertices.Unlock();c.SetVertexShader(&vs);c.SetPixelShader(&ps);c.SetVertexBuffer(0,&vertices,0,8,&declaration);c.SetDepthEnable(Display2::E_Bool_False);c.SetDepthStencilSurface(nullptr);c.SetCullMode(Display2::E_CullMode_None);c.SetBlendEnable(Display2::E_Bool_False);c.SetAlphaTestEnable(Display2::E_Bool_False);c.SetColourWriteEnable(15);Display2::C_SamplerState sampler;sampler.SetTextureAddress(Display2::E_TextureAddress_Clamp);sampler.SetTextureFilter(Display2::E_TextureFilter_Point,Display2::E_TextureFilter_Point,Display2::E_TextureFilter_Point);c.SetSamplerState(0,sampler);
    auto verify=[&](const char* file,const std::vector<U8>& bytes){Display::C_Texture2D texture;require(Display::CreateTexture2DFromFile(file,&texture),"Original PC L8 file helper rejected valid image");require(texture.GetFormat()==Display2::E_TextureFormat_L8&&texture.GetWidth()==word(bytes,16)&&texture.GetHeight()==word(bytes,12),"L8 file metadata changed");U32 offset=128;for(U32 l=0;l<texture.GetLevels();++l){const U32 w=texture.GetWidth(l),h=texture.GetHeight(l);auto raw=texture.LockRect2D(l,16);require(raw.pBits&&raw.pitch>=w,"L8 GPU raw rows unavailable");bool exact=true;for(U32 y=0;y<h;++y)exact&=!std::memcmp(raw.pBits+y*raw.pitch,bytes.data()+offset+y*w,w);texture.UnlockRect2D(l);require(exact,"L8 tight file rows/mips changed during padded GPU streaming");Display2::C_Surface target;require(native.CreateSurface(w,h,Display2::E_Flags_Colour,Display2::E_SurfaceFormat_A8R8G8B8,Display2::E_Multisample_None,nullptr,&target),"L8 sampling GPU target failed");c.SetColourSurface(0,&target);c.SetTexture(0,&texture);const F32 dimensions[]={F32(w),F32(h),F32(l),0};c.SetPixelShaderConstantF(0,dimensions,1);c.BeginScene();c.Clear(Display2::E_Clear_Colour,0);c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);c.EndScene();auto pixels=target.LockRect(16);require(pixels.pBits,"L8 sampled GPU pixels unavailable");exact=true;for(U32 y=0;y<h;++y)for(U32 x=0;x<w;++x){const U8 value=bytes[offset+y*w+x];const U8* pixel=pixels.pBits+y*pixels.pitch+x*4;exact&=pixel[0]==value&&pixel[1]==value&&pixel[2]==value&&pixel[3]==255;}target.UnlockRect();require(exact,"L8 sampling did not replicate luminance to RGB with alpha one");c.SetColourSurface(0,device.GetNativeColourSurface());native.Destroy(&target);offset+=w*h;}require(offset<=bytes.size(),"L8 fixture read beyond DDS payload");c.SetTexture(0,nullptr);device.Destroy(&texture);};
    auto valid=dds(false);write(root/"valid.dds",valid);verify("valid.dds",valid);auto numeric=dds(true);write(root/"numeric.dds",numeric);verify("numeric.dds",numeric);auto stale=valid;word(stale,20,512);write(root/"stale-pitch.dds",stale);verify("stale-pitch.dds",stale);if(const char* retail=std::getenv("BLUR_MAC_GHOST_DDS")){const auto bytes=read(retail);write(root/"ghost.dds",bytes);verify("ghost.dds",bytes);std::cout<<"Original private ghost_mask.dds: exact GPU rows and LLL1 sampled view passed\n";}
    std::vector<std::vector<U8>> invalid;auto ambiguous=stale;ambiguous.push_back(0);invalid.push_back(ambiguous);for(auto field:{80U,88U,92U,96U,100U,104U}){auto bad=valid;word(bad,field,word(bad,field)^1);invalid.push_back(bad);}auto shortFile=valid;shortFile.pop_back();invalid.push_back(shortFile);auto levels=valid;word(levels,28,32);invalid.push_back(levels);for(const auto& bad:invalid){write(root/"bad.dds",bad);Display::C_Texture2D failed;require(!Display::CreateTexture2DFromFile("bad.dds",&failed)&&!failed.IsCreated(),"Malformed L8 flags/masks/pitch/mips/payload created GPU storage");}
    FailureState state;{PostProcess::C_Manager post;new FileEffect(post,state);require(!post.Create()&&!post.IsRendererCreated()&&state.created==1&&state.destroyed==1,"Failed original native postprocess graph reported ready or skipped rollback");for(U32 i=0;i<PostProcess::E_Shader_Count;++i)require(!post.GetShader(i)->IsCreated(),"Failed native graph retained a weighted shader after rollback");}
    native.Destroy(&vertices);native.Destroy(&declaration);native.Destroy(&vs);native.Destroy(&ps);require(native.WaitIdle(),"L8 fixture GPU completion failed");device.DestroyVolatile();device.Destroy();Sys::SetDefaultFileSystem(nullptr);std::cout<<"Native PC L8 DDS: strict standard luminance/numeric format, exact padded GPU rows/mips and LLL1 shader pixels, malformed rejection, genuine graph Create failure and weighted/effect rollback PASS\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
